  from 2 * 2 do eval end;
  eval in
theorem nested = (2 + 3) * 2 == 10 proof from (2 + 3) * 2 do
    from 2 + 3 do eval end;
    eval
  end;
  eval in
theorem algebra = 4 / 2 == 2 proof from 4 / 2 do rewrite 2 end end;
  eval in
theorem under_fun = (fun x: Int -> x + 0) == (fun x: Int -> x) proof from x + 0 do rewrite x end end;
  axiom refl_eq end in
theorem rev_nil = rev([]) == [] proof from rev([]) do eval end;
  axiom refl_eq end in
theorem rev_cons = forall x: Int -> forall t: [Int] -> rev(x :: t) == rev(t) @ [x] proof from rev(x :: t) do eval end;
  axiom refl_eq end in
theorem app_cons = forall y: Int -> forall l: [Int] -> forall m: [Int] -> (y :: l) @ m == y :: (l @ m) proof from (y :: l) @ m do eval end;
  axiom refl_eq end in
theorem snoc = forall xs: [Int] -> forall x: Int -> rev(xs @ [x]) == x :: rev(xs) proof induction xs
  | [] =>
    from rev([]) do axiom rev_nil end end;
    from rev([] @ [x]) do
      from [] @ [x] do eval end;
      eval;
      from $e([]) do eval end;
      eval
    end;
    from x :: [] do eval end;
    axiom refl_eq end
  | y :: t =>
    from (y :: t) @ [x] do axiom app_cons end end;
    from rev(y :: (t @ [x])) do axiom rev_cons end end;
    from rev(t @ [x]) do axiom ih end end;
    from (x :: rev(t)) @ [y] do axiom app_cons end end;
    from rev(y :: t) do axiom rev_cons end end;
    axiom refl_eq end
  end in
theorem invol = forall xs: [Int] -> rev(rev(xs)) == xs proof induction xs
  | [] =>
    from rev([]) do axiom rev_nil end end;
    from rev([]) do axiom rev_nil end end;
    axiom refl_eq end
  | x :: t =>
    from rev(x :: t) do axiom rev_cons end end;
    from rev(rev(t) @ [x]) do axiom snoc end end;
    from rev(rev(t)) do axiom ih end end;
    axiom refl_eq end
  end in
theorem total_nil = total([]) == 0 proof from total([]) do eval end;
  axiom refl_eq end in
theorem total_cons = forall p: Int -> forall rest: [Int] -> total(p :: rest) == p + total(rest) proof ?? in
